#include "EffectProcessor.h"

void EffectProcessor::processBuffer(juce::AudioBuffer<float>& b,double sr,const std::vector<EffectSettings>& s,int block)
{EffectChain chain;chain.setEffects(s);chain.prepare(sr,block,b.getNumChannels());chain.process(b);}

void AudioOperations::normalize(juce::AudioBuffer<float>& b,float targetDb,float ceilingDb)
{float peak=0;for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<b.getNumSamples();++i)peak=juce::jmax(peak,std::abs(b.getSample(c,i)));if(peak<=1.0e-12f)return;const float target=juce::jmin(juce::Decibels::decibelsToGain(targetDb),juce::Decibels::decibelsToGain(ceilingDb));b.applyGain(target/peak);}
void AudioOperations::reverse(juce::AudioBuffer<float>& b){for(int c=0;c<b.getNumChannels();++c){auto* x=b.getWritePointer(c);for(int i=0,j=b.getNumSamples()-1;i<j;++i,--j)std::swap(x[i],x[j]);}}
void AudioOperations::fadeIn(juce::AudioBuffer<float>& b,double sr,double ms){const int n=juce::jlimit(0,b.getNumSamples(),(int)(sr*ms/1000.0));if(n<=0)return;for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<n;++i)b.setSample(c,i,b.getSample(c,i)*(float)i/(float)juce::jmax(1,n-1));}
void AudioOperations::fadeOut(juce::AudioBuffer<float>& b,double sr,double ms){const int n=juce::jlimit(0,b.getNumSamples(),(int)(sr*ms/1000.0));if(n<=0)return;for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<n;++i){const int p=b.getNumSamples()-n+i;b.setSample(c,p,b.getSample(c,p)*(float)(n-1-i)/(float)juce::jmax(1,n-1));}}
bool AudioOperations::trim(juce::AudioBuffer<float>& b,float thresholdDb){const float t=juce::Decibels::decibelsToGain(thresholdDb);int first=0,last=b.getNumSamples()-1;for(;first<b.getNumSamples();++first){float p=0;for(int c=0;c<b.getNumChannels();++c)p=juce::jmax(p,std::abs(b.getSample(c,first)));if(p>t)break;}for(;last>=first;--last){float p=0;for(int c=0;c<b.getNumChannels();++c)p=juce::jmax(p,std::abs(b.getSample(c,last)));if(p>t)break;}if(first>last)return false;if(first>0||last<b.getNumSamples()-1){juce::AudioBuffer<float> cut(b.getNumChannels(),last-first+1);for(int c=0;c<b.getNumChannels();++c)cut.copyFrom(c,0,b,c,first,cut.getNumSamples());b=std::move(cut);}return true;}

juce::var RenderOperations::toVar()const{auto*o=new juce::DynamicObject();o->setProperty("normalize",normalize);o->setProperty("reverse",reverse);o->setProperty("trimSilence",trimSilence);o->setProperty("fadeInMs",fadeInMs);o->setProperty("fadeOutMs",fadeOutMs);o->setProperty("normalizeTargetDb",normalizeTargetDb);o->setProperty("normalizeCeilingDb",normalizeCeilingDb);o->setProperty("trimThresholdDb",trimThresholdDb);return juce::var(o);}
RenderOperations RenderOperations::fromVar(const juce::var&v){RenderOperations o;if(auto*d=v.getDynamicObject()){o.normalize=d->getProperty("normalize");o.reverse=d->getProperty("reverse");o.trimSilence=d->getProperty("trimSilence");o.fadeInMs=d->getProperty("fadeInMs");o.fadeOutMs=d->getProperty("fadeOutMs");o.normalizeTargetDb=d->getProperty("normalizeTargetDb");o.normalizeCeilingDb=d->getProperty("normalizeCeilingDb");o.trimThresholdDb=d->getProperty("trimThresholdDb");}return o;}
